        (v_dataset_id, ores_utility_system_tenant_id_fn(), 0, 'CorridorVarianceDispersionSwap', 'MultiAssetOption({AssetClass})', 'Corridor Variance Dispersion Swap (with Cap and/or Floor) - EQ, FX or COMM'),
