        (v_dataset_id, ores_utility_system_tenant_id_fn(), 0, 'OutperformanceOption', 'MultiAssetOption({AssetClass})', 'OutperformanceOption'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 0, 'ForwardVolatilityAgreement', 'SingleAssetOption({AssetClass})', 'Forward Volatility Agreement'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 0, 'CorrelationSwap', 'MultiAssetOption({AssetClass})', 'Correlation Swap'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 0, 'ConstantMaturityVolatilitySwap', 'SingleUnderlyingIrOption', 'CMS Volatility Swap'),
