            worstPerformance = performance;
          END;
        END;

        IF BermudanBarrier == 1 THEN
          FOR d IN (1, SIZE(BarrierSchedule), 1) DO
            IF knockedIn == 0 THEN
              FOR u IN (1, SIZE(Underlyings), 1) DO
