        (v_dataset_id, ores_utility_system_tenant_id_fn(), 0, 'Accumulator01', 'default', 3, 'Alive', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 0, 'Accumulator01', 'default', 4, 'Fixing', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 0, 'Accumulator02', 'default', 1, 'currentNotional', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 0, 'Accumulator02', 'default', 2, 'PayCcy', 'notionalCurrency'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 0, 'Accumulator02', 'default', 3, 'KnockedOut', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 0, 'Accumulator02', 'default', 4, 'Fixing', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 0, 'Accumulator02', 'FD', 1, 'currentNotional', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 0, 'Accumulator02', 'FD', 2, 'PayCcy', 'notionalCurrency'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 0, 'Accumulator02', 'FD', 3, 'Fixing', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 0, 'WindowBarrierOption', 'default', 1, 'TriggerProbability', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 0, 'WindowBarrierOption', 'default', 2, 'ExerciseProbability', null),
